11	fn sri_sha512(bytes: &[u8]) -> String {
12	    let mut opts = IntegrityOpts::new().algorithm(Algorithm::Sha512);
13	    opts.input(bytes);
14	    opts.result().to_string()
15	}
16	
17	fn sha1_hex(bytes: &[u8]) -> String {
18	    let mut opts = IntegrityOpts::new().algorithm(Algorithm::Sha1);
19	    opts.input(bytes);
20	    sha1_hex_from_integrity_opts(opts)
21	}
22	
23	fn run_stream(
24	    bytes: &[u8],
25	    dist: Option<&Value>,
26	    declared_length: Option<u64>,
27	) -> (Result<u64, crate::error::RegistryError>, PathBuf, TempDir) {
28	    let tmp = TempDir::new().unwrap();
29	    let dest = tmp.path().join("out.tgz");
30	    let b64 = BASE64.encode(bytes);
31	    let result =
32	        stream_decode_verify_and_write("foo-1.0.0.tgz", &b64, declared_length, dist, &dest);
33	    (result, dest, tmp)
34	}
35	
36	#[test]
37	fn stream_writes_matching_tarball() {
38	    let bytes = b"hello-world";
39	    let dist = json!({ "integrity": sri_sha512(bytes), "shasum": sha1_hex(bytes) });
40	    let (result, dest, _tmp) = run_stream(bytes, Some(&dist), Some(bytes.len() as u64));
41	    let written = result.unwrap();
42	    assert_eq!(written, bytes.len() as u64);
43	    assert_eq!(std::fs::read(&dest).unwrap(), bytes);
44	}
