1340	/// identity to another. Applied to *every* branch of those handlers
1341	/// — success and error alike — so an intermediary can't latch onto
1342	/// a 401 either.
1343	fn private_no_cache(mut response: Response) -> Response {
1344	    use axum::http::HeaderValue;
1345	    let headers = response.headers_mut();
1346	    headers.insert(header::CACHE_CONTROL, HeaderValue::from_static("private, no-store"));
1347	    headers.insert(header::VARY, HeaderValue::from_static("Authorization"));
1348	    response
1349	}
