1351	/// `PUT /:pkg` — publish a new version (or republish). Body is the
1352	/// full packument with `_attachments` carrying the tarball bytes
1353	/// base64-encoded.
1354	async fn publish_package(
1355	    state: &AppState,
1356	    identity: &Identity,
1357	    raw_name: &str,
1358	    body: axum::body::Bytes,
1359	) -> Response {
1360	    let name = match PackageName::parse(raw_name) {
1361	        Ok(n) => n,
1362	        Err(err) => return error_response(&err),
1363	    };
1364	
1365	    let incoming: Value = match serde_json::from_slice(&body) {
1366	        Ok(v) => v,
1367	        Err(err) => return error_response(&RegistryError::Json(err)),
1368	    };
1369	
1370	    // Reject a publish whose body name disagrees with the URL.
1371	    // npm/verdaccio return 400 here too; without this check a
1372	    // misrouted PUT silently overwrites the wrong on-disk
1373	    // package.json with another package's manifest.
1374	    let body_name = incoming.get("name").and_then(Value::as_str);
1375	    if body_name.is_some_and(|body_name| body_name != name.as_str()) {
1376	        return error_response(&RegistryError::BadRequest {
1377	            reason: format!(
1378	                "package in URL ({:?}) does not match body ({:?})",
1379	                name.as_str(),
1380	                body_name.unwrap_or(""),
1381	            ),
1382	        });
1383	    }
1384	
1385	    let validated = match validate_publish_doc(state, identity, name, incoming).await {
1386	        Ok(validated) => validated,
1387	        Err(err) => return error_response(&err),
1388	    };
1389	
1390	    // Serialize the read-merge-write against other writers of this same
1391	    // package on this instance, so a concurrent publish can't read the
1392	    // same `existing`, merge a different version, and overwrite ours.
1393	    // Held until this function returns, past the packument write below.
1394	    let _packument_guard = state.inner.package_locks.lock(validated.name.as_str()).await;
1395	
1396	    let staged = match stage_publish(state, validated, &now_iso()).await {
1397	        Ok(staged) => staged,
1398	        Err(err) => return error_response(&err),
1399	    };
1400	    if let Err(err) = commit_publishes(state, vec![staged]).await {
1401	        return error_response(&err);
1402	    }
1403	    publish_created_response()
1404	}
