//! Deleted after verification; do not commit.

use axum::{
    body::{Body, to_bytes},
    http::{Request, StatusCode},
};
use base64::{Engine, engine::general_purpose::STANDARD as BASE64};
use pnpr::{Config, MaxUsers, router};
use serde_json::{Value, json};
use std::{
    net::{Ipv4Addr, SocketAddr, SocketAddrV4},
    path::PathBuf,
};
use tempfile::TempDir;
use tower::ServiceExt;

fn static_config(storage: PathBuf) -> Config {
    let listen = SocketAddr::V4(SocketAddrV4::new(Ipv4Addr::LOCALHOST, 4873));
    let mut config = Config::static_serve(listen, storage);
    config.public_url = "http://example.test".to_string();
    config.auth.htpasswd.max_users = MaxUsers::Unlimited;
    config
}

async fn body_json(body: Body) -> Value {
    let bytes = to_bytes(body, usize::MAX).await.unwrap().to_vec();
    serde_json::from_slice(&bytes).unwrap()
}

async fn add_user_and_get_token(app: axum::Router, username: &str) -> (axum::Router, String) {
    let path = format!("/-/user/org.couchdb.user:{username}");
    let body = json!({
        "_id": format!("org.couchdb.user:{username}"),
        "name": username, "password": "secret", "email": "a@b.c", "type": "user", "roles": [],
    });
    let req = Request::put(&path)
        .header("content-type", "application/json")
        .body(Body::from(serde_json::to_vec(&body).unwrap()))
        .unwrap();
    let resp = app.clone().oneshot(req).await.unwrap();
    assert_eq!(resp.status(), StatusCode::CREATED);
    let payload = body_json(resp.into_body()).await;
    let token = payload["token"].as_str().unwrap().to_string();
    (app, token)
}

fn sri_sha512(bytes: &[u8]) -> String {
    let mut opts = ssri::IntegrityOpts::new().algorithm(ssri::Algorithm::Sha512);
    opts.input(bytes);
    opts.result().to_string()
}

fn sample_publish_body(name: &str, version: &str, tarball: &[u8]) -> Value {
    let filename = format!("{name}-{version}.tgz");
    json!({
        "_id": name, "name": name, "dist-tags": { "latest": version },
        "versions": { version: {
            "name": name, "version": version,
            "dist": {
                "tarball": format!("http://localhost:4873/{name}/-/{filename}"),
                "integrity": sri_sha512(tarball),
            }
        }},
        "_attachments": { filename: {
            "content_type": "application/octet-stream",
            "data": BASE64.encode(tarball), "length": tarball.len()
        }}
    })
}

fn put(path: &str, token: &str, body: &Value) -> Request<Body> {
    Request::put(path)
        .header("content-type", "application/json")
        .header("Authorization", format!("Bearer {token}"))
        .body(Body::from(serde_json::to_vec(body).unwrap()))
        .unwrap()
}

async fn publish_first(app: &axum::Router, token: &str, storage: &std::path::Path) {
    let body = sample_publish_body("m", "1.0.0", b"original-bytes");
    let resp = app.clone().oneshot(put("/m", token, &body)).await.unwrap();
    assert_eq!(resp.status(), StatusCode::CREATED);
    assert!(storage.join("m/m-1.0.0.tgz").exists());
}

// Req 5: metadata-only re-publish (same integrity, no attachment) applies deprecated → 201.
#[tokio::test]
async fn req5_metadata_only_deprecate() {
    let tmp = TempDir::new().unwrap();
    let storage = tmp.path().to_path_buf();
    let app = router(static_config(storage.clone()));
    let (app, token) = add_user_and_get_token(app, "alice").await;
    publish_first(&app, &token, &storage).await;

    let integrity = sri_sha512(b"original-bytes");
    let body = json!({
        "name": "m", "dist-tags": { "latest": "1.0.0" },
        "versions": { "1.0.0": {
            "name": "m", "version": "1.0.0", "deprecated": "please upgrade",
            "dist": { "tarball": "http://example.test/m/-/m-1.0.0.tgz", "integrity": integrity }
        }},
    });
    let resp = app.clone().oneshot(put("/m", &token, &body)).await.unwrap();
    assert_eq!(resp.status(), StatusCode::CREATED, "metadata-only re-publish must be accepted");

    let get = app.oneshot(Request::get("/m").body(Body::empty()).unwrap()).await.unwrap();
    let pack = body_json(get.into_body()).await;
    assert_eq!(pack["versions"]["1.0.0"]["deprecated"], "please upgrade", "deprecated applied");
    assert_eq!(pack["versions"]["1.0.0"]["dist"]["integrity"], sri_sha512(b"original-bytes"));
    // Tarball bytes untouched.
    assert_eq!(std::fs::read(storage.join("m/m-1.0.0.tgz")).unwrap(), b"original-bytes");
}

